/**
 * Durable per-session Bitbucket channel state, persisted with the turn so
 * channel stream-event handlers can rebuild a repo-bound handle without
 * re-parsing the webhook.
 */
export function emptyBitbucketChannelState(overrides = {}) {
    return {
        dialect: null,
        repoFullName: "",
        repoUuid: null,
        pullRequestId: null,
        headSha: null,
        triggeringCommentId: null,
        deliveryId: null,
        eventType: null,
        ...overrides,
    };
}
export function bitbucketChannelStateForEvent(input) {
    return emptyBitbucketChannelState({
        dialect: input.repository.dialect,
        repoFullName: input.repository.fullName,
        repoUuid: input.repository.uuid ?? null,
        pullRequestId: input.pullRequestId ?? null,
        headSha: input.headSha ?? null,
        triggeringCommentId: input.triggeringCommentId ?? null,
        deliveryId: input.deliveryId ?? null,
        eventType: input.eventType,
    });
}
